mapper.select:
SELECT /*selectMasterMdSrSrCmsStateList*/ A.SR_NO AS SR_NO, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.USER_ID) AS REQ_USER_NAME, TO_CHAR (A.PH_DATE, 'YYYY/MM/DD HH24:MI') AS PH_DATE, NVL (A.SR_SUBJECT, A.REQ_REMARK) AS SR_SUBJECT, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'SR01' AND CODE = A.SYS_TYPE) AS SYS_TEXT, TO_CHAR (A.REQ_DATE, 'YYYY/MM/DD HH24:MI') AS REQ_DATE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'SR02' AND CODE = A.REQ_TYPE) AS REQ_TEXT, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'SR05' AND CODE = A.REQ_SR_TYPE) AS REQ_SR_TEXT, A.USER_ID AS USER_ID, (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = 'KRKORE0001' AND TYPE = 'C001' AND CODE = A.REQ_DEPT) REQ_DEPT_NAME FROM KEPASRDT A WHERE TO_CHAR (A.REQ_DATE, 'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date} AND A.RECV_FLAG = 'GA'
AND A.SYS_TYPE = #{st_sys_type}
AND A.REQ_TYPE = #{st_req_type}
AND A.REQ_SR_TYPE = #{st_req_sr_type}
AND (A.SR_SUBJECT LIKE '%'||#{st_remark}||'%' or A.REQ_REMARK LIKE '%'||#{st_remark}||'%')
ORDER BY A.PH_DATE DESC
ORDER BY A.REQ_DATE DESC
